const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "kvhttp", .root_module = mod });
    b.installArtifact(exe);

    const run = b.addRunArtifact(exe);
    run.step.dependOn(b.getInstallStep());
    if (b.args) |args| run.addArgs(args);
    b.step("run", "Run the server").dependOn(&run.step);

    const tests = b.addTest(.{ .root_module = mod });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Request routing for the key-value API.

const App = @This();

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const mem = std.mem;

const Store = @import("Store.zig");
const http = @import("http.zig");
const Request = http.Request;
const Response = http.Response;

store: *Store,

const kv_prefix = "/kv/";
const max_key_len = 64;

pub const Error = Allocator.Error || Io.Cancelable;

/// Dispatches `req`. Response bodies are allocated with `arena`.
pub fn handle(app: App, io: Io, arena: Allocator, req: Request) Error!Response {
    const path = req.path;
    if (mem.eql(u8, path, "/health")) {
        if (!mem.eql(u8, req.method, "GET")) return methodNotAllowed("GET");
        return .{ .status = .ok, .body = "ok", .content_type = "text/plain" };
    }
    if (mem.eql(u8, path, "/kv")) {
        if (!mem.eql(u8, req.method, "GET")) return methodNotAllowed("GET");
        const keys = try app.store.keys(io, arena);
        const body = try std.json.Stringify.valueAlloc(arena, keys, .{});
        return .{ .status = .ok, .body = body, .content_type = "application/json" };
    }
    if (mem.startsWith(u8, path, kv_prefix)) {
        const key = path[kv_prefix.len..];
        if (!isValidKey(key)) return .{ .status = .bad_request };
        return app.handleKey(io, arena, req, key);
    }
    return .{ .status = .not_found };
}

fn handleKey(app: App, io: Io, arena: Allocator, req: Request, key: []const u8) Error!Response {
    const Method = enum { GET, PUT, DELETE };
    const method = std.meta.stringToEnum(Method, req.method) orelse
        return methodNotAllowed("GET, PUT, DELETE");
    switch (method) {
        .GET => {
            const value = try app.store.get(io, arena, key) orelse return .{ .status = .not_found };
            return .{ .status = .ok, .body = value, .content_type = "application/octet-stream" };
        },
        .PUT => return switch (try app.store.put(io, key, req.body)) {
            .created => .{ .status = .created },
            .replaced => .{ .status = .ok },
        },
        .DELETE => return .{ .status = if (try app.store.delete(io, key)) .no_content else .not_found },
    }
}

fn methodNotAllowed(allow: []const u8) Response {
    return .{ .status = .method_not_allowed, .allow = allow };
}

/// A key matches `[A-Za-z0-9_-]{1,64}`.
pub fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > max_key_len) return false;
    for (key) |c| switch (c) {
        'A'...'Z', 'a'...'z', '0'...'9', '_', '-' => {},
        else => return false,
    };
    return true;
}

test isValidKey {
    try std.testing.expect(isValidKey("a"));
    try std.testing.expect(isValidKey("A-z_09"));
    try std.testing.expect(isValidKey("x" ** 64));
    try std.testing.expect(!isValidKey(""));
    try std.testing.expect(!isValidKey("x" ** 65));
    try std.testing.expect(!isValidKey("a/b"));
    try std.testing.expect(!isValidKey("bad.key"));
    try std.testing.expect(!isValidKey("caf\xc3\xa9"));
}

test "routing" {
    const io = std.testing.io;
    var arena_state: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    var store: Store = .init(std.testing.allocator);
    defer store.deinit();
    const app: App = .{ .store = &store };

    const Case = struct { method: []const u8, path: []const u8, body: []const u8 = "", status: http.Status, out: ?[]const u8 = null };
    const cases = [_]Case{
        .{ .method = "GET", .path = "/health", .status = .ok, .out = "ok" },
        .{ .method = "POST", .path = "/health", .status = .method_not_allowed },
        .{ .method = "GET", .path = "/nope", .status = .not_found },
        .{ .method = "GET", .path = "/kv/", .status = .bad_request },
        .{ .method = "GET", .path = "/kv/a/b", .status = .bad_request },
        .{ .method = "PUT", .path = "/kv/b", .body = "2", .status = .created },
        .{ .method = "PUT", .path = "/kv/a", .body = "1", .status = .created },
        .{ .method = "PUT", .path = "/kv/a", .body = "one", .status = .ok },
        .{ .method = "GET", .path = "/kv/a", .status = .ok, .out = "one" },
        .{ .method = "PATCH", .path = "/kv/a", .status = .method_not_allowed },
        .{ .method = "GET", .path = "/kv", .status = .ok, .out = "[\"a\",\"b\"]" },
        .{ .method = "DELETE", .path = "/kv", .status = .method_not_allowed },
        .{ .method = "DELETE", .path = "/kv/a", .status = .no_content },
        .{ .method = "DELETE", .path = "/kv/a", .status = .not_found },
        .{ .method = "GET", .path = "/kv/a", .status = .not_found },
    };
    for (cases) |c| {
        const res = try app.handle(io, arena, .{ .method = c.method, .path = c.path, .body = c.body });
        try std.testing.expectEqual(c.status, res.status);
        if (c.out) |out| try std.testing.expectEqualStrings(out, res.body);
    }
}

//! Thread-safe in-memory key-value store.
//!
//! Keys and values are owned by the store (allocated with `gpa`). Readers get
//! copies allocated from a caller-supplied allocator, so the lock is never held
//! while a response is being written to a slow client.

const Store = @This();

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

gpa: Allocator,
mutex: Io.Mutex = .init,
map: std.StringHashMapUnmanaged([]u8) = .empty,

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(s: *Store) void {
    var it = s.map.iterator();
    while (it.next()) |entry| {
        s.gpa.free(entry.key_ptr.*);
        s.gpa.free(entry.value_ptr.*);
    }
    s.map.deinit(s.gpa);
    s.* = undefined;
}

pub const PutResult = enum { created, replaced };

/// Stores a copy of `value` under `key`.
pub fn put(s: *Store, io: Io, key: []const u8, value: []const u8) (Allocator.Error || Io.Cancelable)!PutResult {
    // Allocate outside the critical section.
    const owned_value = try s.gpa.dupe(u8, value);
    errdefer s.gpa.free(owned_value);

    const old_value: ?[]u8, const result: PutResult = blk: {
        try s.mutex.lock(io);
        defer s.mutex.unlock(io);

        const gop = try s.map.getOrPut(s.gpa, key);
        if (gop.found_existing) {
            const old = gop.value_ptr.*;
            gop.value_ptr.* = owned_value;
            break :blk .{ old, .replaced };
        }
        gop.key_ptr.* = s.gpa.dupe(u8, key) catch |err| {
            s.map.removeByPtr(gop.key_ptr);
            return err;
        };
        gop.value_ptr.* = owned_value;
        break :blk .{ null, .created };
    };

    if (old_value) |old| s.gpa.free(old);
    return result;
}

/// Returns a copy of the value stored under `key`, allocated with `allocator`.
pub fn get(s: *Store, io: Io, allocator: Allocator, key: []const u8) (Allocator.Error || Io.Cancelable)!?[]u8 {
    try s.mutex.lock(io);
    defer s.mutex.unlock(io);

    const value = s.map.get(key) orelse return null;
    return try allocator.dupe(u8, value);
}

/// Removes `key`; returns whether it was present.
pub fn delete(s: *Store, io: Io, key: []const u8) Io.Cancelable!bool {
    const removed = blk: {
        try s.mutex.lock(io);
        defer s.mutex.unlock(io);
        break :blk s.map.fetchRemove(key);
    };
    const entry = removed orelse return false;
    s.gpa.free(entry.key);
    s.gpa.free(entry.value);
    return true;
}

/// Returns copies of every key, sorted ascending by byte value.
pub fn keys(s: *Store, io: Io, allocator: Allocator) (Allocator.Error || Io.Cancelable)![][]const u8 {
    const list = blk: {
        try s.mutex.lock(io);
        defer s.mutex.unlock(io);

        const list = try allocator.alloc([]const u8, s.map.count());
        errdefer allocator.free(list);
        var it = s.map.keyIterator();
        var i: usize = 0;
        errdefer for (list[0..i]) |k| allocator.free(k);
        while (it.next()) |key| : (i += 1) {
            list[i] = try allocator.dupe(u8, key.*);
        }
        break :blk list;
    };
    std.mem.sortUnstable([]const u8, list, {}, lessThan);
    return list;
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

test "put, get, delete, keys" {
    const io = std.testing.io;
    var arena: std.heap.ArenaAllocator = .init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();

    var store: Store = .init(std.testing.allocator);
    defer store.deinit();

    try std.testing.expectEqual(PutResult.created, try store.put(io, "b", "1"));
    try std.testing.expectEqual(PutResult.replaced, try store.put(io, "b", "2"));
    try std.testing.expectEqual(PutResult.created, try store.put(io, "a", ""));
    try std.testing.expectEqualStrings("2", (try store.get(io, a, "b")).?);
    try std.testing.expectEqualStrings("", (try store.get(io, a, "a")).?);
    try std.testing.expectEqual(null, try store.get(io, a, "c"));

    const ks = try store.keys(io, a);
    try std.testing.expectEqual(2, ks.len);
    try std.testing.expectEqualStrings("a", ks[0]);
    try std.testing.expectEqualStrings("b", ks[1]);

    try std.testing.expect(try store.delete(io, "b"));
    try std.testing.expect(!try store.delete(io, "b"));
    try std.testing.expectEqual(null, try store.get(io, a, "b"));
}

//! Minimal HTTP/1.1 request parsing and response serialization.
//!
//! Only what the key-value server needs: one request per connection, bodies
//! delimited by `Content-Length` or chunked transfer encoding.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const mem = std.mem;

pub const max_body_bytes = 1024 * 1024;
pub const max_head_bytes = 64 * 1024;

pub const Status = enum(u10) {
    ok = 200,
    created = 201,
    no_content = 204,
    bad_request = 400,
    not_found = 404,
    method_not_allowed = 405,
    content_too_large = 413,
    request_header_fields_too_large = 431,
    internal_server_error = 500,

    pub fn phrase(s: Status) []const u8 {
        return switch (s) {
            .ok => "OK",
            .created => "Created",
            .no_content => "No Content",
            .bad_request => "Bad Request",
            .not_found => "Not Found",
            .method_not_allowed => "Method Not Allowed",
            .content_too_large => "Content Too Large",
            .request_header_fields_too_large => "Request Header Fields Too Large",
            .internal_server_error => "Internal Server Error",
        };
    }

    /// Responses with these statuses never carry a body or `Content-Length`.
    fn isBodiless(s: Status) bool {
        return s == .no_content;
    }
};

pub const Header = struct {
    name: []const u8,
    value: []const u8,
};

pub const Response = struct {
    status: Status,
    body: []const u8 = "",
    content_type: ?[]const u8 = null,
    allow: ?[]const u8 = null,

    pub fn write(r: Response, w: *Io.Writer) Io.Writer.Error!void {
        try w.print("HTTP/1.1 {d} {s}\r\n", .{ @intFromEnum(r.status), r.status.phrase() });
        if (!r.status.isBodiless()) try w.print("Content-Length: {d}\r\n", .{r.body.len});
        try w.writeAll("Connection: close\r\n");
        if (r.content_type) |v| try w.print("Content-Type: {s}\r\n", .{v});
        if (r.allow) |v| try w.print("Allow: {s}\r\n", .{v});
        try w.writeAll("\r\n");
        if (!r.status.isBodiless()) try w.writeAll(r.body);
        try w.flush();
    }
};

pub const Request = struct {
    method: []const u8,
    /// Request target with any query string removed.
    path: []const u8,
    body: []const u8,
};

/// Protocol violations that are answered with an error status.
pub const ProtocolError = error{
    BadRequest,
    ContentTooLarge,
    HeaderFieldsTooLarge,
};

pub const ReadError = ProtocolError || Allocator.Error || Io.Reader.Error;

pub fn statusFor(err: ProtocolError) Status {
    return switch (err) {
        error.BadRequest => .bad_request,
        error.ContentTooLarge => .content_too_large,
        error.HeaderFieldsTooLarge => .request_header_fields_too_large,
    };
}

/// Reads one request from `r`. All returned slices are allocated with
/// `arena`. The reader's buffer must be at least `max_head_bytes` long.
pub fn readRequest(arena: Allocator, r: *Io.Reader) ReadError!Request {
    const head_len = try findHeadEnd(r);
    const head = try arena.dupe(u8, r.buffered()[0 .. head_len - 4]);
    r.toss(head_len);

    var lines = mem.splitSequence(u8, head, "\r\n");
    const request_line = lines.first();

    var parts = mem.splitScalar(u8, request_line, ' ');
    const method = parts.next().?;
    const target = parts.next() orelse return error.BadRequest;
    const version = parts.next() orelse return error.BadRequest;
    if (parts.next() != null or !mem.startsWith(u8, version, "HTTP/")) return error.BadRequest;

    var content_length: ?[]const u8 = null;
    var transfer_encoding: ?[]const u8 = null;
    while (lines.next()) |line| {
        const header = try parseHeaderLine(line);
        // Later duplicates win, as with a dictionary keyed by lowercase name.
        if (std.ascii.eqlIgnoreCase(header.name, "content-length")) {
            content_length = header.value;
        } else if (std.ascii.eqlIgnoreCase(header.name, "transfer-encoding")) {
            transfer_encoding = header.value;
        }
    }

    const body = if (transfer_encoding != null and std.ascii.indexOfIgnoreCase(transfer_encoding.?, "chunked") != null)
        try readChunkedBody(arena, r)
    else blk: {
        const length = try parseContentLength(content_length orelse "0");
        const body = try arena.alloc(u8, length);
        try r.readSliceAll(body);
        break :blk body;
    };

    const path = if (mem.indexOfScalar(u8, target, '?')) |q| target[0..q] else target;
    return .{ .method = method, .path = path, .body = body };
}

/// Fills `r` until its buffer holds the full request head; returns the
/// head's length including the terminating blank line.
fn findHeadEnd(r: *Io.Reader) (ProtocolError || Io.Reader.Error)!usize {
    const terminator = "\r\n\r\n";
    var scanned: usize = 0;
    while (true) {
        const buf = r.buffered();
        if (mem.indexOfPos(u8, buf, scanned, terminator)) |i| return i + terminator.len;
        scanned = buf.len -| (terminator.len - 1);
        if (buf.len >= max_head_bytes or buf.len == r.buffer.len) return error.HeaderFieldsTooLarge;
        try r.fillMore();
    }
}

fn parseHeaderLine(line: []const u8) ProtocolError!Header {
    const colon = mem.indexOfScalar(u8, line, ':') orelse return error.BadRequest;
    const name = line[0..colon];
    if (name.len == 0 or isSpace(name[0]) or isSpace(name[name.len - 1])) return error.BadRequest;
    return .{ .name = name, .value = mem.trim(u8, line[colon + 1 ..], &whitespace) };
}

const whitespace = [_]u8{ ' ', '\t', '\r', '\n', 0x0b, 0x0c };

fn isSpace(c: u8) bool {
    return mem.indexOfScalar(u8, &whitespace, c) != null;
}

fn parseContentLength(raw: []const u8) ProtocolError!usize {
    if (raw.len == 0) return error.BadRequest;
    for (raw) |c| if (!std.ascii.isDigit(c)) return error.BadRequest;
    const length = std.fmt.parseUnsigned(usize, raw, 10) catch return error.ContentTooLarge;
    if (length > max_body_bytes) return error.ContentTooLarge;
    return length;
}

fn readChunkedBody(arena: Allocator, r: *Io.Reader) ReadError![]u8 {
    var body: std.ArrayList(u8) = .empty;
    while (true) {
        const line = try takeLine(r);
        const size_text = mem.trim(u8, line[0 .. mem.indexOfScalar(u8, line, ';') orelse line.len], &whitespace);
        const size = std.fmt.parseUnsigned(usize, size_text, 16) catch |err| switch (err) {
            error.Overflow => return error.ContentTooLarge,
            error.InvalidCharacter => return error.BadRequest,
        };
        if (size == 0) {
            // Skip trailers up to the terminating blank line.
            while ((try takeLine(r)).len != 0) {}
            return body.items;
        }
        if (body.items.len + size > max_body_bytes) return error.ContentTooLarge;
        try r.readSliceAll(try body.addManyAsSlice(arena, size));
        if (!mem.eql(u8, try r.takeArray(2), "\r\n")) return error.BadRequest;
    }
}

/// Takes one CRLF-terminated line, returned without the terminator.
fn takeLine(r: *Io.Reader) (ProtocolError || Io.Reader.Error)![]u8 {
    const line = r.takeDelimiterInclusive('\n') catch |err| switch (err) {
        error.StreamTooLong => return error.HeaderFieldsTooLarge,
        else => |e| return e,
    };
    if (line.len < 2 or line[line.len - 2] != '\r') return error.BadRequest;
    return line[0 .. line.len - 2];
}

const testing = std.testing;

fn parseFixed(arena: Allocator, raw: []const u8) ReadError!Request {
    var reader: Io.Reader = .fixed(raw);
    return readRequest(arena, &reader);
}

test "content-length request" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const req = try parseFixed(arena.allocator(), "PUT /kv/a?x=1 HTTP/1.1\r\nHost: x\r\ncontent-length: 5\r\n\r\nhello");
    try testing.expectEqualStrings("PUT", req.method);
    try testing.expectEqualStrings("/kv/a", req.path);
    try testing.expectEqualStrings("hello", req.body);
}

test "chunked request" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const req = try parseFixed(arena.allocator(), "PUT /kv/a HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n" ++
        "3\r\nabc\r\n2;ext=1\r\nde\r\n0\r\nTrailer: x\r\n\r\n");
    try testing.expectEqualStrings("abcde", req.body);
}

test "malformed requests" {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    try testing.expectError(error.BadRequest, parseFixed(a, "GET /\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseFixed(a, "GET / FTP/1\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseFixed(a, "GET / HTTP/1.1\r\nnocolon\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseFixed(a, "GET / HTTP/1.1\r\n x: y\r\n\r\n"));
    try testing.expectError(error.BadRequest, parseFixed(a, "GET / HTTP/1.1\r\nContent-Length: -1\r\n\r\n"));
    try testing.expectError(error.ContentTooLarge, parseFixed(a, "GET / HTTP/1.1\r\nContent-Length: 1048577\r\n\r\n"));
    try testing.expectError(error.ContentTooLarge, parseFixed(a, "GET / HTTP/1.1\r\nContent-Length: 99999999999999999999999\r\n\r\n"));
}

test "response serialization" {
    var buf: [256]u8 = undefined;
    var w: Io.Writer = .fixed(&buf);
    try (Response{ .status = .ok, .body = "ok", .content_type = "text/plain" }).write(&w);
    try testing.expectEqualStrings("HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\nContent-Type: text/plain\r\n\r\nok", w.buffered());

    w = .fixed(&buf);
    try (Response{ .status = .no_content }).write(&w);
    try testing.expectEqualStrings("HTTP/1.1 204 No Content\r\nConnection: close\r\n\r\n", w.buffered());
}

//! kvhttp: an in-memory HTTP/1.1 key-value server.
//!
//! Usage: app [--host <addr>] <port>
//!
//! One request is handled per connection; every response carries an exact
//! Content-Length (except 204) and the connection is closed afterwards.

const std = @import("std");
const Io = std.Io;
const net = Io.net;
const Allocator = std.mem.Allocator;

const App = @import("App.zig");
const Store = @import("Store.zig");
const http = @import("http.zig");

const log = std.log.scoped(.kvhttp);

/// Idle connections are dropped after this long without receiving data.
const read_timeout_seconds = 30;
/// After an early error response, at most this much unread request data is
/// drained so the client sees the response instead of a connection reset.
const max_drain_bytes = 4 * http.max_body_bytes;

const Server = struct {
    io: Io,
    gpa: Allocator,
    app: App,

    fn handleConnection(s: *Server, stream: net.Stream) void {
        defer stream.close(s.io);
        s.serveOne(stream) catch |err| switch (err) {
            error.OutOfMemory => log.err("out of memory while handling request", .{}),
            // The peer went away or timed out; there is nobody to answer.
            error.ReadFailed, error.WriteFailed, error.EndOfStream, error.Canceled => {},
        };
    }

    fn serveOne(s: *Server, stream: net.Stream) !void {
        setReceiveTimeout(stream);

        var arena_state: std.heap.ArenaAllocator = .init(s.gpa);
        defer arena_state.deinit();
        const arena = arena_state.allocator();

        const read_buffer = try arena.alloc(u8, http.max_head_bytes);
        var reader = stream.reader(s.io, read_buffer);
        var write_buffer: [4096]u8 = undefined;
        var writer = stream.writer(s.io, &write_buffer);

        var fully_read = true;
        const response: http.Response = if (http.readRequest(arena, &reader.interface)) |req|
            s.app.handle(s.io, arena, req) catch |err| switch (err) {
                error.Canceled => |e| return e,
                error.OutOfMemory => .{ .status = .internal_server_error },
            }
        else |err| switch (err) {
            error.BadRequest, error.ContentTooLarge, error.HeaderFieldsTooLarge => |e| blk: {
                fully_read = false;
                break :blk .{ .status = http.statusFor(e) };
            },
            error.OutOfMemory => blk: {
                fully_read = false;
                break :blk .{ .status = .internal_server_error };
            },
            error.ReadFailed, error.EndOfStream => |e| return e,
        };

        try response.write(&writer.interface);

        if (!fully_read) {
            // Lingering close: closing with unread input would make the kernel
            // reset the connection, possibly discarding the response.
            stream.shutdown(s.io, .send) catch return;
            var drained: usize = 0;
            while (drained < max_drain_bytes) {
                drained += reader.interface.discard(.limited(max_drain_bytes - drained)) catch break;
            }
        }
    }
};

fn setReceiveTimeout(stream: net.Stream) void {
    const tv: std.posix.timeval = .{ .sec = read_timeout_seconds, .usec = 0 };
    std.posix.setsockopt(
        stream.socket.handle,
        std.posix.SOL.SOCKET,
        std.posix.SO.RCVTIMEO,
        std.mem.asBytes(&tv),
    ) catch |err| log.warn("cannot set receive timeout: {t}", .{err});
}

const Options = struct {
    host: []const u8 = "127.0.0.1",
    port: u16,
};

fn usage() noreturn {
    std.debug.print("usage: app [--host HOST] PORT\n", .{});
    std.process.exit(2);
}

fn parseArgs(args: std.process.Args) Options {
    var it = args.iterate();
    _ = it.skip();
    var host: ?[]const u8 = null;
    var port: ?u16 = null;
    while (it.next()) |arg| {
        if (std.mem.eql(u8, arg, "--host")) {
            host = it.next() orelse usage();
        } else if (std.mem.startsWith(u8, arg, "--host=")) {
            host = arg["--host=".len..];
        } else if (std.mem.eql(u8, arg, "-h") or std.mem.eql(u8, arg, "--help")) {
            usage();
        } else if (port == null) {
            port = std.fmt.parseUnsigned(u16, arg, 10) catch usage();
        } else {
            usage();
        }
    }
    return .{ .host = host orelse "127.0.0.1", .port = port orelse usage() };
}

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const gpa = init.gpa;
    const options = parseArgs(init.minimal.args);

    const address = net.IpAddress.parse(options.host, options.port) catch |err| {
        log.err("invalid host '{s}': {t}", .{ options.host, err });
        std.process.exit(2);
    };
    var listener = address.listen(io, .{ .reuse_address = true, .kernel_backlog = 1024 }) catch |err| {
        log.err("cannot listen on {f}: {t}", .{ address, err });
        std.process.exit(1);
    };
    defer listener.deinit(io);
    log.info("listening on {f}", .{address});

    var store: Store = .init(gpa);
    defer store.deinit();
    var server: Server = .{ .io = io, .gpa = gpa, .app = .{ .store = &store } };

    var connections: Io.Group = .init;
    defer connections.cancel(io);

    while (true) {
        const stream = listener.accept(io) catch |err| switch (err) {
            error.Canceled => |e| return e,
            error.ConnectionAborted => continue,
            else => {
                log.warn("accept failed: {t}", .{err});
                // Typically descriptor exhaustion; back off instead of spinning.
                io.sleep(.fromMilliseconds(10), .awake) catch |e| return e;
                continue;
            },
        };
        connections.concurrent(io, Server.handleConnection, .{ &server, stream }) catch {
            // No thread available: serve inline rather than dropping the client.
            server.handleConnection(stream);
        };
    }
}

